// n8n Code node (JavaScript)

// Get incoming items
const items = $input.all();

function cleanDocDump(raw) {
  if (typeof raw !== 'string') return '';

  let txt = raw;

  // Normalize line breaks
  txt = txt.replace(/\r\n/g, '\n');

  // Remove {empty object}
  txt = txt.replace(/\{empty object\}/g, '');

  // Optional: remove some noisy keys
  const noisyPatterns = [
    /\bstartIndex\b.*?:.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\bendIndex\b.*?:.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\brgbColor\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\bfontSize\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\bparagraphStyle\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\btableCellStyle\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\btableRowStyle\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
  ];
  for (const p of noisyPatterns) {
    txt = txt.replace(p, '');
  }

  // Collapse multiple spaces
  txt = txt.replace(/[ \t]+/g, ' ');
  // Collapse long runs of \\\n markers into real newlines
  txt = txt.replace(/\\\\n\s*/g, '\n');

  // Split into lines and keep only content-like lines
  const lines = txt
    .split('\n')
    .map(l => l.trim())
    .filter(l => l && !l.startsWith('title : ENG_RESUME_MAIN'));

  return lines.join('\n').trim();
}

const out = items.map(item => {
  // IMPORTANT: this is where your dump actually is
  const rawDump = item.json.text || '';

  const cleanedText = cleanDocDump(rawDump);

  return {
    json: {
      original: rawDump,
      text: cleanedText, // cleaned CV text for AI
    },
  };
});

return out;

// In n8n Code node

// Get all incoming items (in case you later process multiple docs)
const items = $input.all();

// We will return one output item per input item
const out = items.map((item) => {
  const doc = item.json || {};
  let text = '';

  function readElements(elements) {
    if (!Array.isArray(elements)) return;

    for (const el of elements) {
      // Paragraphs
      if (el.paragraph && Array.isArray(el.paragraph.elements)) {
        for (const pe of el.paragraph.elements) {
          const run = pe.textRun;
          if (run && typeof run.content === 'string') {
            text += run.content;
          }
        }
      }

      // Tables (can be nested)
      else if (el.table && Array.isArray(el.table.tableRows)) {
        for (const row of el.table.tableRows) {
          if (!Array.isArray(row.tableCells)) continue;
          for (const cell of row.tableCells) {
            readElements(cell.content || []);
          }
        }
      }

      // Table of contents
      else if (el.tableOfContents) {
        readElements(el.tableOfContents.content || []);
      }
    }
  }

  // Docs API puts structural elements under body.content
  if (doc.body && Array.isArray(doc.body.content)) {
    readElements(doc.body.content);
  }

  return {
    json: {
      rawDoc: doc, // keep original if you need it later
      text: text,  // flattened text for AI
    },
  };
});

return out;

