    }
    .header-job-title { font-size: 15pt; font-weight: 600; color: #333; text-align: right; }
    .contact { font-size: 8pt; text-align: left; margin-bottom: 4px; }
    .contact a { color: #0066cc; text-decoration: none; }
    .contact a:hover { text-decoration: underline; }
    .ext-arrow {
      font-size: 7pt;
      color: #0066cc;
      vertical-align: baseline;  /* or just remove this line */
      line-height: 1;
      margin-left: 1px;          /* small spacing from text */
    }

    /* ── section headings ── */
    h2 {
      font-size: 10pt; margin-top: 9px; margin-bottom: 2px;
      border-bottom: 1px solid #0066cc; padding-bottom: 2px;
      font-weight: bold; color: #0066cc; text-transform: uppercase;
    }

    /* ── summary ── */
    .summary-section { margin-bottom: 4px; font-size: 9pt; line-height: 1.33; }

    /* ── two-column body ── */
    .two-columns { display: flex; gap: 0.25in; }
    .left-column  { width: 34%; font-size: 9pt; }
    .right-column { width: 66%; font-size: 9pt; }

    /* ── SKILLS — horizontal pills ── */
    .skill-row {
      display: flex; flex-wrap: wrap; align-items: baseline;
      margin-bottom: 3px; gap: 3px;
    }
    .skill-cat {
      font-weight: bold; font-size: 8pt; white-space: nowrap;
