<body>

  <!-- ══ HEADER ══ -->
  <div class="header-section">
    <div class="name-title-row">
      <h1>SAIYUDH MANNAN</h1>
      <div class="header-job-title">${stripHtml(tailoredCV.job_title || 'Data Engineer')}</div>
    </div>
    <div class="contact">
      <span>${stripHtml(tailoredCV.contact.email || '')}</span> •
      <span>+49 15906396002</span> •
