// ── Step 2: German DIN 5008 rule — lowercase first letter of body ──
// The salutation ends with a comma in German, so the first word
// of the opening paragraph must start with a lowercase letter.
function lowerFirstLetter(str) {
  if (!str) return str;
  // Skip any leading whitespace
  let i = 0;
  while (i < str.length && str[i] === ' ') i++;
  if (i >= str.length) return str;
  return str.slice(0, i) + str[i].toLowerCase() + str.slice(i + 1);
}

