// n8n Code node (JavaScript)

// Get incoming items
const items = $input.all();

function cleanDocDump(raw) {
  if (typeof raw !== 'string') return '';

  let txt = raw;

  // Normalize line breaks
  txt = txt.replace(/\r\n/g, '\n');

  // Remove {empty object}
  txt = txt.replace(/\{empty object\}/g, '');

  // Optional: remove some noisy keys
  const noisyPatterns = [
    /\bstartIndex\b.*?:.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\bendIndex\b.*?:.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\brgbColor\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\bfontSize\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\bparagraphStyle\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\btableCellStyle\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
    /\btableRowStyle\b.*?(?=\s+[a-zA-Z_]+\s*:|$)/g,
  ];
  for (const p of noisyPatterns) {
    txt = txt.replace(p, '');
  }

  // Collapse multiple spaces
  txt = txt.replace(/[ \t]+/g, ' ');
  // Collapse long runs of \\\n markers into real newlines
  txt = txt.replace(/\\\\n\s*/g, '\n');

  // Split into lines and keep only content-like lines
  const lines = txt
    .split('\n')
    .map(l => l.trim())
    .filter(l => l && !l.startsWith('title : ENG_RESUME_MAIN'));

  return lines.join('\n').trim();
}

const out = items.map(item => {
  // IMPORTANT: this is where your dump actually is
  const rawDump = item.json.text || '';

  const cleanedText = cleanDocDump(rawDump);

  return {
    json: {
      original: rawDump,
      text: cleanedText, // cleaned CV text for AI
    },
  };
});

return out;

// ============================================================
// CV GER JSON → HTML  (n8n Code node)
// German CV with horizontal pill layout + ↗ arrows on links
// ============================================================

const tailoredCV = $('CV_Maker GER Agent').first().json.output || {};

// ── helpers ────────────────────────────────────────────────
const extractHref = (val) => {
  if (!val) return '';
  if (typeof val !== 'string') return '';
  if (!val.includes('href=')) return val;
  const match = val.match(/href="([^"]+)"/);
  return match ? match[1] : val;
};

const stripHtml = (s) =>
  typeof s === 'string' ? s.replace(/<[^>]*>/g, '').trim() : '';

const removeLeadingLabel = (s) => {
  if (typeof s !== 'string') return '';
  return s.replace(/^\s*<b>.*?<\/b>\s*:|\s*[^:]{1,25}:\s+/i, '').trim();
};

const removeDoubleDash = (s) => {
  if (typeof s !== 'string') return '';
  return s.replace(/\s*--\s*/g, ', ').trim();
};

// ── contact cleanup ─────────────────────────────────────────
tailoredCV.contact = tailoredCV.contact || {};
tailoredCV.contact.linkedin  = extractHref(tailoredCV.contact.linkedin);
tailoredCV.contact.github    = extractHref(tailoredCV.contact.github);
tailoredCV.contact.portfolio = extractHref(tailoredCV.contact.portfolio);

// ── job / company meta ──────────────────────────────────────
const jobData     = $('Loop jobs').first().json;
const companyName = jobData.companyName || 'Unternehmen';
const jobTitle    = jobData.jobTitle    || 'Position';

const sanitize = (str) =>
  String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const fileName = `saiyudh_mannan_lebenslauf_${sanitize(companyName)}_${sanitize(jobTitle)}`;

// ── normalise arrays ────────────────────────────────────────
const workExp         = Array.isArray(tailoredCV.work_experience) ? tailoredCV.work_experience : [];
const educationArr    = Array.isArray(tailoredCV.education)       ? tailoredCV.education       : [];
const projectsArr     = Array.isArray(tailoredCV.projects)        ? tailoredCV.projects        : [];
const certificatesArr = Array.isArray(tailoredCV.certificates)    ? tailoredCV.certificates    : [];

const skillsObj   = tailoredCV.skills || {};
const progSkills  = Array.isArray(skillsObj.programming)   ? skillsObj.programming   : [];
const cloudSkills = Array.isArray(skillsObj.cloud)         ? skillsObj.cloud         : [];
const llmAiSkills = Array.isArray(skillsObj.llm_ai)        ? skillsObj.llm_ai        : [];
const vizSkills   = Array.isArray(skillsObj.visualization) ? skillsObj.visualization : [];
const langSkills  = Array.isArray(skillsObj.languages)     ? skillsObj.languages     : [];

const psc          = tailoredCV.personal_skills_and_competencies || {};
const languagesArr = langSkills.length
  ? langSkills
  : Array.isArray(psc.languages) ? psc.languages : [];

// ── cleanup responsibilities & project bullets ──────────────
workExp.forEach((exp) => {
  if (!exp) return;
  exp.responsibilities = Array.isArray(exp.responsibilities)
    ? exp.responsibilities
        .map((r) => removeDoubleDash(stripHtml(removeLeadingLabel(r))))
        .filter(Boolean)
    : [];
});

projectsArr.forEach((proj) => {
  if (!proj) return;
  if (!Array.isArray(proj.bullets) || !proj.bullets.length) {
    proj.bullets = typeof proj.description === 'string' && proj.description.trim()
      ? [proj.description.trim()] : [];
  }
  proj.bullets = proj.bullets.map((b) => removeDoubleDash(stripHtml(b))).filter(Boolean);
});

// ── SKILLS — HORIZONTAL PILL LAYOUT (German labels) ─────────
const buildKeySkillsHTML = () => {
  const groups = [
    { label: 'Programmierung', arr: progSkills },
    { label: 'Cloud',          arr: cloudSkills },
    { label: 'LLM & KI',       arr: llmAiSkills },
    { label: 'Visualisierung', arr: vizSkills },
    { label: 'Sprachen',       arr: languagesArr },
  ].filter(g => g.arr.length > 0);

  if (!groups.length) return '';

  return groups.map(({ label, arr }) => {
    const items = arr
      .map(s => `<span class="skill-pill">${stripHtml(s)}</span>`)
      .join(' ');
    return `
      <div class="skill-row">
        <span class="skill-cat">${label}:</span>
        <span class="skill-pills">${items}</span>
      </div>`;
  }).join('');
};

// ── CERTIFICATES — with ↗ arrow on linked certs ─────────────
const buildCertificatesHTML = () => {
  if (!certificatesArr.length) return '<p class="placeholder">Details auf Anfrage verfügbar</p>';
  return certificatesArr.map(cert => {
    if (!cert) return '';
    const name = stripHtml(cert.name || '');
    const link = cert.link || '';
    if (!name) return '';
    return link
      ? `<div class="cert-item"><a href="${link}" target="_blank">${name} <span class="ext-arrow">↗</span></a></div>`
      : `<div class="cert-item">${name}</div>`;
  }).filter(Boolean).join('');
};

// ── HTML ─────────────────────────────────────────────────────
const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Lebenslauf - Saiyudh Mannan</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: Arial, sans-serif;
      font-size: 9pt;
      line-height: 1.28;
      max-width: 8.5in;
      margin: 0.1in 0.3in;
      color: #000;
    }

    /* ── header ── */
    h1 { font-size: 20pt; font-weight: bold; margin: 0; }
    .name-title-row {
      display: flex; justify-content: space-between; align-items: baseline;
      margin-bottom: 2px;
    }
    .header-job-title { font-size: 15pt; font-weight: 600; color: #333; text-align: right; }
    .contact { font-size: 8pt; text-align: left; margin-bottom: 4px; }
    .contact a { color: #0066cc; text-decoration: none; }
    .contact a:hover { text-decoration: underline; }
    .ext-arrow {
      font-size: 7pt; color: #0066cc; vertical-align: baseline;
      line-height: 1; margin-left: 1px;
    }

    /* ── section headings ── */
    h2 {
      font-size: 10pt; margin-top: 9px; margin-bottom: 2px;
      border-bottom: 1px solid #0066cc; padding-bottom: 2px;
      font-weight: bold; color: #0066cc; text-transform: uppercase;
    }

    /* ── summary ── */
    .summary-section { margin-bottom: 4px; font-size: 9pt; line-height: 1.33; }

    /* ── two-column body ── */
    .two-columns { display: flex; gap: 0.25in; }
    .left-column  { width: 34%; font-size: 9pt; }
    .right-column { width: 66%; font-size: 9pt; }

    /* ── SKILLS — horizontal pills ── */
    .skill-row {
      display: flex; flex-wrap: wrap; align-items: baseline;
      margin-bottom: 3px; gap: 3px;
    }
    .skill-cat {
      font-weight: bold; font-size: 8pt; white-space: nowrap;
      margin-right: 2px; flex-shrink: 0;
    }
    .skill-pills { display: flex; flex-wrap: wrap; gap: 2px; }
    .skill-pill {
      font-size: 7.5pt; background: #f0f4ff; border: 0.5px solid #b0c0e8;
      border-radius: 2px; padding: 0 3px; white-space: nowrap;
      color: #1a1a2e;
    }

    /* ── certificates ── */
    .cert-item { font-size: 8pt; margin-bottom: 2px; line-height: 1.3; }
    .cert-item a { color: #0066cc; text-decoration: none; }
    .cert-item a:hover { text-decoration: underline; }

    /* ── projects ── */
    .project { margin-bottom: 5px; }
    .project-header {
      display: flex; justify-content: space-between; align-items: baseline; gap: 6px;
    }
    .project-title  { font-weight: bold; font-size: 9pt; }
    .github-link    { font-size: 8pt; color: #0066cc; text-decoration: none; white-space: nowrap; }
    .github-link:hover { text-decoration: underline; }
    .project ul     { margin-left: 12px; margin-top: 1px; }
    .project li     { margin-bottom: 1px; font-size: 8.5pt; }

    /* ── work experience ── */
    .experience { margin-bottom: 6px; }
    .job-title-row, .degree-row {
      display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 1px;
    }
    .exp-title, .edu-degree { font-weight: bold; font-size: 9pt; }
    .company-name           { font-weight: 400; font-size: 9pt; margin-bottom: 0; }
    .duration, .edu-year    {
      font-style: normal; color: #666; white-space: nowrap; margin-left: 8px; font-size: 8.5pt;
    }

    ul { margin-left: 13px; margin-top: 2px; }
    li { margin-bottom: 1px; font-size: 9pt; }

    /* ── education ── */
    .education-item { margin-bottom: 5px; }
    .edu-institution { font-style: normal; color: #333; font-size: 8.5pt; }

    a { color: #000; text-decoration: none; }
    .placeholder { color: #888; font-size: 8pt; }
  </style>
</head>
<body>

  <!-- ══ HEADER ══ -->
  <div class="header-section">
    <div class="name-title-row">
      <h1>SAIYUDH MANNAN</h1>
      <div class="header-job-title">${stripHtml(tailoredCV.job_title || 'Dateningenieur')}</div>
    </div>
    <div class="contact">
      <span>${stripHtml(tailoredCV.contact.email || '')}</span> •
      <span>+49 15906396002</span> •
      <span>Magdeburg, Deutschland</span> •
      <a href="${tailoredCV.contact.linkedin || '#'}" target="_blank">LinkedIn <span class="ext-arrow">↗</span></a> •
      <a href="${tailoredCV.contact.github   || '#'}" target="_blank">GitHub <span class="ext-arrow">↗</span></a> •
      <a href="${tailoredCV.contact.portfolio|| '#'}" target="_blank">Portfolio <span class="ext-arrow">↗</span></a>
    </div>
  </div>

  <!-- ══ PROFIL (full-width) ══ -->
  <div class="summary-section">
    <h2>PROFIL</h2>
    ${
      typeof tailoredCV.professional_summary === 'string'
        ? `<p>${stripHtml(tailoredCV.professional_summary)}</p>`
        : Array.isArray(tailoredCV.professional_summary)
        ? `<p>${tailoredCV.professional_summary.map(stripHtml).join(' ')}</p>`
        : ''
    }
  </div>

  <!-- ══ TWO-COLUMN BODY ══ -->
  <div class="two-columns">

    <!-- LEFT: Kernkompetenzen → Zertifikate → Projekte -->
    <div class="left-column">

      <h2>KERNKOMPETENZEN</h2>
      <div class="skills-section">
        ${buildKeySkillsHTML()}
      </div>

      <h2>ZERTIFIKATE</h2>
      <div class="certs-section">
        ${buildCertificatesHTML()}
      </div>

      <h2>PROJEKTE</h2>
      <div class="projects-section">
        ${projectsArr.length
          ? projectsArr.map(proj => `
            <div class="project">
              <div class="project-header">
                <div class="project-title">${stripHtml(proj.name || '')}</div>
                ${proj.link
                  ? `<a href="${proj.link}" target="_blank" class="github-link">GitHub ↗</a>`
