                <div class="exp-title">${stripHtml(exp.title || '')}</div>
                <div class="duration">${stripHtml(exp.duration || '')}</div>
              </div>
              <div class="company-name">${stripHtml(exp.company || '')}</div>
              <ul>
                ${(exp.responsibilities || [])
                  .map(r => `<li>${stripHtml(r)}</li>`)
                  .join('')}
              </ul>
            </div>`).join('')
          : '<p class="placeholder">Details auf Anfrage verfügbar</p>'
        }
      </div>

      ${(() => {
        const sections = ['AUSBILDUNG', 'WEITERBILDUNG', 'SONSTIGES'];
        const grouped = {};
        sections.forEach(s => { grouped[s] = []; });
        educationArr.forEach(edu => {
          const sec = (edu.section || 'AUSBILDUNG').toUpperCase();
          if (grouped[sec]) grouped[sec].push(edu);
          else grouped['AUSBILDUNG'].push(edu);
        });

        const renderEntry = (edu) => `
          <div class="education-item">
            <div class="degree-row">
              <div class="edu-degree">${stripHtml(edu.degree || '')}</div>
              <div class="edu-year">${stripHtml(edu.year || '')}</div>
