            <div class="edu-institution">${stripHtml(edu.institution || '')}</div>
            ${Array.isArray(edu.bullets) && edu.bullets.length
              ? `<ul>${edu.bullets.map(b => `<li>${stripHtml(b)}</li>`).join('')}</ul>`
              : ''}
          </div>`;

        return sections
          .filter(s => grouped[s].length > 0)
          .map(s => `
            <h2>${s}</h2>
            <div>${grouped[s].map(renderEntry).join('')}</div>
          `).join('');
      })()}

    </div><!-- /right -->

  </div><!-- /two-columns -->

</body>
</html>`;

return {
  json: {
    html,
    fileName,
    companyName,
    jobTitle,
    language: 'de',
  },
};

// Input: Perplexity JSON on each item
const items = $input.all();

return items.map(item => {
  const content = item.json.choices?.[0]?.message?.content ?? null;

  let email = null;

  if (typeof content === 'string') {
    const trimmed = content.trim();

    // If model returned "null" or empty, treat as not found
    if (trimmed.toLowerCase() === 'null' || trimmed === '') {
      email = null;
    } else {
      // Extract email pattern
      const match = trimmed.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);

      if (match) {
        // Reject masked emails like c****@helsing.ai
        if (match[0].includes('****') || match[0].includes('***')) {
          email = null;
        } else {
          email = match[0];
        }
      } else {
        email = null;
      }
    }
  }

  return {
    json: {
      ...item.json,
      hrEmail: email,
    },
  };
});

