// Code node: "Extract Drive IDs"
// Mode: Run Once for Each Item

const item = $input.item;
const json = item.json;

const extractId = (url) => {
  if (!url) return '';
  const m1 = url.match(/id=([^&]+)/);      // ?id=...&export=download
  const m2 = url.match(/\/d\/([^/]+)/);    // /file/d/<ID>/view
  return (m1 && m1[1]) || (m2 && m2[1]) || '';
};

json.cvFileId = extractId(json.cvPath);
json.coverFileId = extractId(json.CoverLetterPath);

return { json, binary: item.binary ?? {} };

// CHANGE if your sheet is not the first one
const sheetId = 0;

// Extract row numbers from nested output
const rows = items
  .map(item => item.json.output["row number"])
  .filter(r => typeof r === "number");

// Sort DESCENDING (critical!)
rows.sort((a, b) => b - a);

// Build batchUpdate delete requests
const requests = rows.map(r => ({
  deleteDimension: {
    range: {
      sheetId,
      dimension: "ROWS",
      startIndex: r - 1, // convert to 0-based
      endIndex: r
    }
  }
}));

return [
  {
    json: {
      requests,
      rowsDeleted: rows
    }
  }
];

const items = $input.all();

const allTitles = items
  .flatMap(i => Array.isArray(i.json.titles) ? i.json.titles : [i.json.titles])
  .filter(title => title !== undefined && title !== null && title !== '')
  .join(',');

// Merge all json objects, later items overwrite earlier keys
const merged = items.reduce((acc, i) => ({ ...acc, ...i.json }), {});

// Override titles with aggregated string
merged.titles = allTitles;

return [{ json: merged }];

// ============================================================
// COVER LETTER HTML BUILDER — n8n Code Node
// ============================================================

// ── Step 1: Get raw output and apply nested JSON safety net ──
let coverLetterData = $('Cover_Letter_Agent1').first().json.output || {};

if (
  coverLetterData.paragraph_1 &&
  typeof coverLetterData.paragraph_1 === 'string' &&
  coverLetterData.paragraph_1.trim().startsWith('{') &&
  (!coverLetterData.paragraph_2 || coverLetterData.paragraph_2 === '')
) {
  try {
    const parsed = JSON.parse(coverLetterData.paragraph_1);
    if (parsed.paragraph_1 && parsed.paragraph_2) {
      coverLetterData = parsed;
    }
  } catch (e) {}
}

// ── Step 2: Fixed contact details ────────────────────────────
const CONTACT_NAME     = 'Saiyudh Mannan';
const CONTACT_EMAIL    = 'saiyudh.mannan@gmail.com';
const CONTACT_PHONE    = '+4915906396002';
const CONTACT_LOCATION = '39104 Magdeburg, Germany';

// ── Step 3: Job data ──────────────────────────────────────────
const jobData      = $('Loop jobs').first().json;
const companyName  = jobData.companyName  || 'Company';
const rawJobTitle  = jobData.jobTitle     || 'Position';
const companyLocation = jobData.location  || '';

// ── Step 4: Subject job title — agent value OR cleaned fallback ──
const subjectJobTitle =
  coverLetterData.subject_job_title ||
  rawJobTitle
    .replace(/\\\\s*[-–|].*$/, '')
    .replace(/\\\\s*\\\\(.*?\\\\)/g, '')
    .trim();

// ── Step 5: Sanitized filename ────────────────────────────────
const sanitize = (str) =>
  String(str || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

const docType  = 'cover_letter';
const fileName = `saiyudh_mannan_${docType}_${sanitize(companyName)}_${sanitize(subjectJobTitle)}`;

// ── Step 6: English date ──────────────────────────────────────
const currentDate = new Date().toLocaleDateString('en-GB', {
  day:   '2-digit',
  month: 'long',
  year:  'numeric',
});

// ── Step 7: Signature ─────────────────────────────────────────
const signatureBase64 = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64');

// ── Step 8: Build skill bullets from paragraph_3 ─────────────
const bulletHtml = coverLetterData.paragraph_3
  ? coverLetterData.paragraph_3
      .split(/\\\\n|•/)
      .map((s) => s.trim())
      .filter((s) => s.length > 0)
      .map((s) => {
        const formatted = s.replace(/^([^:]+):\s*/, '<strong>$1</strong>: ');
        return `<li>${formatted}</li>`;
      })
      .join('')
  : '<li>Skills loading...</li>';

// ── Step 9: Build full HTML ───────────────────────────────────
const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Cover Letter - ${CONTACT_NAME}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: Arial, sans-serif;
      font-size: 9pt;
      line-height: 1.28;
      max-width: 8.5in;
      margin: 0.1in 0.3in;
      color: #000;
    }

    /* ── Header block ── */
    .header            { margin-bottom: 16px; }
    .sender-info       { font-size: 8pt; margin-bottom: 4px; line-height: 1.28; text-align: right; }
    .sender-info a     { color: #0066cc; text-decoration: none; }

    /* ── Section headings — identical to CV h2 ── */
    h2 {
      font-size: 10pt;
      margin-top: 9px;
      margin-bottom: 2px;
      border-bottom: 1px solid #0066cc;
      padding-bottom: 2px;
      font-weight: bold;
      color: #0066cc;
      text-transform: uppercase;
    }

    /* ── Recipient ── */
    .recipient         { font-size: 9pt; margin-bottom: 16px; line-height: 1.28; }

    /* ── Date: right-aligned, sits after recipient ── */
    .date              { font-size: 9pt; margin-bottom: 16px; text-align: right; }

    /* ── Subject ── */
    .subject           { font-size: 9pt; font-weight: bold; margin-bottom: 20px; }

    /* ── Body ── */
    .salutation        { font-size: 9pt; margin-bottom: 16px; }
    .paragraph         { font-size: 9pt; line-height: 1.33; margin-bottom: 10px; text-align: left; margin-top: 5px; }

    /* ── Skill bullets — matches CV ul/li ── */
    .skills-list       { margin: 4px 0 16px 14px; font-size: 9pt; line-height: 1.28; }
    .skills-list li    { margin-bottom: 1px; }
    .skills-list strong { font-weight: bold; }

    /* ── Closing & signature ── */
    .closing           { font-size: 9pt; margin-top: 6px; margin-bottom: 6px; }
    .signature-section { margin-top: 5px; font-size: 9pt; line-height: 1.28; }
    .signature-img     { max-width: 180px; height: auto; }

    a { color: #000; text-decoration: none; }
  </style>
</head>
<body>

  <!-- Sender address — right aligned -->
  <div class="header">
    <div class="sender-info">
      <strong>${CONTACT_NAME}</strong><br>
      ${CONTACT_LOCATION}<br>
      ${CONTACT_EMAIL}<br>
      ${CONTACT_PHONE}
    </div>
  </div>

  <!-- Recipient block — left aligned -->
  <div class="recipient">
    <strong>Human Resources Department</strong><br>
    ${companyName}<br>
    ${companyLocation ? `${companyLocation}<br>` : ''}
  </div>

  <!-- Date — right aligned, after recipient -->
  <div class="date">
    Magdeburg, ${currentDate}
  </div>

  <!-- Subject line — no label -->
  <div class="subject">
    Application for ${subjectJobTitle}
  </div>

  <div class="salutation">
    Dear Hiring Manager,
  </div>

  <!-- Paragraph 1: Opening — Why This Company -->
  <div class="paragraph">
    ${coverLetterData.paragraph_1 || 'Opening paragraph loading...'}
  </div>

  <!-- Paragraph 2: Who You Are + What You Offer -->
  <div class="paragraph">
    ${coverLetterData.paragraph_2 || 'Background paragraph loading...'}
  </div>

  <!-- Paragraph 3: Skill Bullets -->
  <div class="skills-list">
    <ul>${bulletHtml}</ul>
  </div>

  <!-- Paragraph 4: Closing — Why This Company + Call to Action -->
  <div class="paragraph">
    ${coverLetterData.paragraph_4 || 'Closing paragraph loading...'}
  </div>

  <div class="closing">
    Best Regards,
  </div>

  <div class="signature-section">
    <img
      src="data:image/png;base64,${signatureBase64}"
      class="signature-img"
      alt="Signature"
    />
    <div style="margin-top: 10px;"><strong>${CONTACT_NAME}</strong></div>
  </div>

</body>
</html>`;

// ── Step 10: Return output ────────────────────────────────────
return {
  json: {
    html,
    fileName,
    language: 'en',
  },
};

