const all = $input.all().map(i => i.json);
const today = new Date().toISOString().split('T')[0];
const total      = all.length;
const unscored   = all.filter(j => !j.Score || j.Score === '').length;
const applyToday = all.filter(j => j.ApplyDate === today).length;
const drafted    = all.filter(j => j.draftReady === 'YES' || j.draftReady === 'GMAIL_DRAFT_CREATED').length;
const inGmail    = all.filter(j => j.draftReady === 'GMAIL_DRAFT_CREATED').length;
const sent       = all.filter(j => String(j.sent).toLowerCase() === 'true').length;
const summary = `Sheet status (${today}):\nTotal: ${total} | Unscored: ${unscored} | Apply today: ${applyToday}\nDrafted: ${drafted} | In Gmail: ${inGmail} | Sent: ${sent}`;
return [{ json: { summary } }];

const out = $json.output || {};
const text = JSON.stringify(out);

const required = [
  'isGerman',
  'job_title',
  'professional_summary',
  'skills',
  'work_experience',
  'education',
  'projects',
  'certificates',
  'personal_skills_and_competencies',
  'contact',
];

const missing = required.filter(k => out[k] === undefined || out[k] === null);

const banned = [
  'example.com',
  'name@example.com',
  'username',
  '[PLACEHOLDER]',
  '[work_experience',
  'AWS Certified Solutions Architect'
];

const foundBanned = banned.filter(x => text.includes(x));

if (missing.length || foundBanned.length) {
  throw new Error(
    `CV QA failed. Missing: ${missing.join(', ')}. Banned text: ${foundBanned.join(', ')}`
  );
}

return $input.item;

